"""Report measured compatible-energy progress and unresolved boundary time error."""
from pathlib import Path
import argparse
import hashlib
import json
import numpy as np
from .compatible_energy_measurements import run
from .compatible_energy_audit import run as run_audit
from .compatible_energy_plot import plot
from .compatible_time_controls import run as run_time_controls
from .boundary_order_probe import run as run_boundary_probe
from .verification_records import write_record


def report(metrics):
    rows = {r["name"]:r for r in metrics["cases"]}
    old = {r["name"]:r for r in metrics["historical_local"]["cases"]}
    lines = ["# Compatible magnetic-energy verification", "",
             "Generated by `python -m examples.verify_compatible_energy`. See the [derivation and method contract](COMPATIBLE_ENERGY.md). The historical cell/Riemann/RK2 method remains separately selectable and remains the solver default; all cases here explicitly select their controls.", "",
             "Positive face-square magnetic energy and natural vacuum boundary work eliminate the identified semidiscrete mismatch for constant bias. SSP RK3 is an optional time integrator. No density/pressure floor, thermal-energy repair, hidden exterior atmosphere or changed shock initial data is introduced. The finite-step response error and physical boundary limitations remain independently measured.", "",
             "## Unchanged independent cylindrical shock", "",
             "Same sharp initial state, r=0.44–0.66 m and |z|≤0.1 m independent error window, zero physical eta and 0.02 s end time. Historical comparisons retain their original provenance; newly measured cases share the current engine fingerprint.", "",
             "| Method / radial cells | Completed | Bz L1/B1 | Pressure L1 [Pa] | Frozen B/rho defect | Response residual [J] | Residual / net outward fluid transfer [%] |",
             "|---|---|---:|---:|---:|---:|---:|"]
    for n in (24,48,96,192,384):
        for label,r in ((f"historical {n}",old[f"shock_local_{n}"]),(f"compatible RK3 {n}",rows[f"shock_{n}"])):
            d,e = r["diagnostics"],r["errors"]
            fraction = 100*d["response_energy_balance_residual_j"]/abs(d["outward_fluid_energy_j"])
            lines.append(f"| {label} | {r['completed']} | {e['Bz_L1_over_upstream_B']:.7g} | {e['pressure_L1_pa']:.7g} | {e['frozen_ratio_defect_L1']:.4g} | {d['response_energy_balance_residual_j']:.7g} | {fraction:.6g} |")
    lines += ["", "Boundary transfer is a demanding energy scale distinct from external source work. A positive finite-time result and converging central shock profiles do not establish converged boundary dynamics.", "",
              "| Compatible RK3 grid | Limited / all Euler stages | Maximum affected cells per stage [%] | Maximum fallback passes | Directly affected reference-window cell-stages |",
              "|---|---:|---:|---:|---:|"]
    for n in (24,48,96,192,384):
        r=rows[f"shock_{n}"];d=r["diagnostics"]
        lines.append(f"| {n} | {d['limited_euler_stages']} / {d['euler_stages']} | {100*d['maximum_limiter_cell_fraction']:.6g} | {d['maximum_limiter_iterations']} | {r['limiter_map']['affected_reference_window_cell_stages']} |")
    lines += ["", "Counts include diagonal neighbors sharing a selected corner. Untouched stencils retain their original derivative; later propagation can still carry boundary errors into the interior.", "",
              "## Time, energy-convention and boundary controls", "",
              "| Case | Completed | Accepted time [s] | Response residual [J] | Numerical interface heat [J] | Minimum density [kg/m³] | Limited / all Euler stages | Failure |",
              "|---|---|---:|---:|---:|---:|---:|---|"]
    for name in ("shock_96","shock_rk2_96","shock_192","shock_rk2_192","shock_half_cfl","shock_rk2_half_cfl",
                 "shock_long_chamber","shock_cell_energy","shock_riemann_boundary","shock_no_limiter","shock_384"):
        r=rows[name];d=r["diagnostics"]
        lines.append(f"| {name} | {r['completed']} | {d['time_s']:.7g} | {d['response_energy_balance_residual_j']:.7g} | {d['numerical_interface_heat_j']:.7g} | {d['minimum_density_kg_m3']:.7g} | {d['limited_euler_stages']} / {d['euler_stages']} | {r.get('failure','—')} |")
    lines += ["", "Energy and boundary ablations change only the named selector relative to the compatible RK3 study. Failed rows are accepted-state records, not final-time convergence points. Limiting uses binary local order reduction and its stage count depends on timestep and stage states.", "",
              "| Shock control relative to compatible baseline | Bz profile L2 change [%] | Pressure profile L2 change [%] |",
              "|---|---:|---:|"]
    for name,base in (("shock_half_cfl","shock_192"),("shock_rk2_half_cfl","shock_rk2_192"),("shock_long_chamber","shock_96")):
        a,b=rows[name],rows[base]
        if a["completed"] and b["completed"]:
            select=(np.asarray(a["profile"]["r_m"])>.44)&(np.asarray(a["profile"]["r_m"])<.66)
            values=[]
            for key in ("Bz_over_upstream_B","pressure"):
                av,bv=np.asarray(a["profile"][key])[select],np.asarray(b["profile"][key])[select]
                values.append(100*np.linalg.norm(av-bv)/np.linalg.norm(bv))
            lines.append(f"| {name} / {base} | {values[0]:.6g} | {values[1]:.6g} |")
    lines += ["", "## Independent finite-step work audit", "",
              "For every accepted step, recomplete the stage flux-rate directions through the vacuum and contract the independent quadratic RK coefficient formula. The measured response increment is used only for comparison. Constant bias makes prescribed source power zero; this audit cannot be applied unchanged to time-varying coils.", "",
              "| Radial cells | CFL | Time [s] | Measured cumulative residual [J] | RK prediction [J] | Spatial prediction [J] | Max stage spatial defect [W] | Max per-step identity error [J] |",
              "|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for audit in metrics["time_audit"]:
        for s in audit["snapshots"]:
            lines.append(f"| {audit['radial_cells']} | {audit['cfl']} | {s['time_s']:.5g} | {s['measured_response_change_j']:.8g} | {s['accumulated_temporal_prediction_j']:.8g} | {s['accumulated_spatial_prediction_j']:.4g} | {s['maximum_stage_spatial_defect_w']:.4g} | {s['maximum_step_identity_error_j']:.4g} |")
    coarse=[a["snapshots"][-1]["measured_response_change_j"] for a in metrics["time_audit"] if a["radial_cells"]==24]
    lines += ["", f"At nr=24, successive CFL halving reduces final RK3 response error by factors {coarse[0]/coarse[1]:.5g} and {coarse[1]/coarse[2]:.5g}, consistent with third-order convergence for this resolved-time case. The sharply limited nr=192 boundary is a separate, nonmonotonic case.", "",
              "Agreement identifies the error mechanism; it does not make the boundary evolution time-converged. No measured energy residual is fed back into the solver. Further temporal-error control or a consistently discretized time-dependent interface treatment is required before claiming convergence of the sharp boundary layer.", "",
              "| First-order spatial control at nr=192 | Completed | Response residual [J] | Bz L1/B1 | Pressure L1 [Pa] |",
              "|---|---|---:|---:|---:|"]
    for r in metrics["first_order_controls"]:
        d,e=r["diagnostics"],r["errors"]
        lines.append(f"| CFL {r['parameters']['cfl']} | {r['completed']} | {d['response_energy_balance_residual_j']:.7g} | {e['Bz_L1_over_upstream_B']:.7g} | {e['pressure_L1_pa']:.7g} |")
    lines += ["", "These supplemental controls retain the original state and end time, use separately fingerprinted inputs, and expose the accuracy cost of the more diffusive spatial baseline. They do not replace the second-order method's convergence requirements.", "",
              "## Experimental fixed boundary strip", "",
              "A separate probe selects first-order shared face/corner fluxes and metric sources incident to one layer of wall/end cells, with the second-order interior retained. This is explicit numerical order reduction, not material resistivity or an energy correction. The neighboring affected region is recorded, and ordinary limiter counters count only any additional adaptive fallback.", "",
              "| Radial cells | CFL | Completed | Bz L1/B1 | Pressure L1 [Pa] | Response residual [J] | Forced / affected cells | Additional adaptive limited stages |",
              "|---:|---:|---|---:|---:|---:|---:|---:|"]
    for r in metrics["boundary_order_probe"]:
        d,e,p=r["diagnostics"],r["errors"],r["boundary_order_probe"]
        lines.append(f"| {r['radial_cells']} | {r['cfl']} | {r['completed']} | {e['Bz_L1_over_upstream_B']:.7g} | {e['pressure_L1_pa']:.7g} | {d['response_energy_balance_residual_j']:.7g} | {p['forced_cell_count']} / {p['affected_cell_count']} | {d['limited_euler_stages']} |")
    lines += ["", "This probe is not the production default. Source-driven skin layers, pulse budgets, boundary accuracy and finer meshes still require verification before adoption. Zero additional adaptive limiting does not mean that the boundary strip is second order. Earlier disposable exploratory runs are not used in this report; the rows above are freshly recorded by the fingerprinted probe driver.", "",
              "## Identical prescribed-source and smooth-solution checks", "",
              "| Pulse | Completed | Source work [J] | Response residual / work [%] | Physical Ohmic heat [J] | Numerical interface heat [J] | Peak speed [m/s] |",
              "|---|---|---:|---:|---:|---:|---:|"]
    for name in ("pulse_16","pulse_32","pulse_64","pulse_half_cfl","pulse_far_matching","pulse_rk2"):
        r=rows[name];d=r["diagnostics"]
        lines.append(f"| {name} | {r['completed']} | {d['source_work_j']:.9g} | {100*d['response_residual_over_source_work']:.7g} | {d['ohmic_heat_j']:.7g} | {d['numerical_interface_heat_j']:.7g} | {d['maximum_speed_m_s']:.7g} |")
    lines += ["", "| Pulse control relative to baseline | Source-work change [%] | Peak-speed change [%] |",
              "|---|---:|---:|"]
    for name,base in (("pulse_half_cfl","pulse_32"),("pulse_far_matching","pulse_16")):
        a,b=rows[name]["diagnostics"],rows[base]["diagnostics"]
        lines.append(f"| {name} / {base} | {100*(a['source_work_j']/b['source_work_j']-1):.6g} | {100*(a['maximum_speed_m_s']/b['maximum_speed_m_s']-1):.6g} |")
    lines += ["", "The response budget excludes external-field self/mutual and coil-circuit energy. Positive interface heat is declared numerical dissipation, separate from physical eta J². Analytic vacuum coil fields still have a finite discrete interior residual, which is not moved into the boundary flux. Source-work convergence does not by itself resolve peak flow or a physical skin layer.", "",
              "| Smooth independent solution | Completed | Flux relative L2 | Limited Euler stages |",
              "|---|---|---:|---:|"]
    for kind in ("advection","diffusion"):
        for n in (12,24,48):
            r=rows[f"{kind}_{n}"]
            lines.append(f"| {kind} {n} | {r['completed']} | {r['flux_relative_L2']:.8g} | {r['diagnostics']['limited_euler_stages']} |")
    completed=[r for r in rows.values() if r["completed"]]
    lines += ["", f"Across the {len(completed)} completed cases, maximum absolute relative mass change is {max(abs(r['diagnostics']['mass_relative_change']) for r in completed):.4g}; fluid energy-flux residual {max(abs(r['diagnostics']['fluid_energy_balance_residual_j']) for r in completed):.4g} J; face divergence {max(r['diagnostics']['max_face_divergence_t_m'] for r in completed):.4g} T/m; vacuum relative residual {max(r['diagnostics']['vacuum_relative_residual'] for r in completed):.4g}.", "",
              "Full parameters, environment/source fingerprints, histories, limiter maps and profiles are in `outputs/compatible_energy_verification/metrics.json`. Progress records are separate and are never convergence evidence.", "",
              "![Compatible energy and time audit](../outputs/compatible_energy_verification/compatible_energy.png)", "",
              "**Remaining scope:** time-converged sharp boundary dynamics, resolved driven skin layers, broader shocks and cold rarefactions, curved equilibrium balance, an evolving free-plasma interface and actual ends, transport/ionization and Hall/kinetic validity, converged formation experiments and the dynamic experimental UI. The full FRC objective remains active and the original Stage 2 gate remains closed."]
    Path("docs/COMPATIBLE_ENERGY_VERIFICATION.md").write_text("\n".join(lines)+"\n")


def verify(directory="outputs/compatible_energy_verification",*,reuse=False):
    directory=Path(directory);directory.mkdir(parents=True,exist_ok=True)
    metrics=run(directory/"cases",reuse=reuse)
    metrics["first_order_controls"]=run_time_controls(directory/"temporal_controls",reuse=reuse)
    metrics["boundary_order_probe"]=[]
    probe_hash=hashlib.sha256(Path("examples/boundary_order_probe.py").read_bytes()).hexdigest()
    for n,cfl in ((24,.2),(48,.2),(96,.2),(96,.1),(192,.2),(192,.1)):
        path=directory/"boundary_order_probe"/f"shock_{n}_cfl{cfl}.json"
        probe=json.loads(path.read_text()) if reuse and path.exists() else None
        if (not probe or "diagnostics" not in probe or probe["provenance"]["boundary_probe_sha256"]!=probe_hash or
            probe["provenance"]["source_sha256"]!=metrics["provenance"]["source_sha256"]):
            probe=run_boundary_probe(n,cfl,directory/"boundary_order_probe")
        metrics["boundary_order_probe"].append(probe)
    metrics["historical_local"]=json.loads(Path("outputs/local_limiter_verification/metrics.json").read_text())
    metrics["time_audit"]=[]
    audit_hash=hashlib.sha256(Path("examples/compatible_energy_audit.py").read_bytes()).hexdigest()
    for n,cfl in ((24,.2),(24,.1),(24,.05),(192,.2)):
        path=directory/"time_audit"/f"shock_{n}_rk3_cfl{cfl}.json"
        audit=json.loads(path.read_text()) if reuse and path.exists() else None
        if (not audit or not audit["completed"] or audit["audit_sha256"]!=audit_hash or
            audit["provenance"]["source_sha256"]!=metrics["provenance"]["source_sha256"]):
            audit=run_audit(n,3,cfl,directory/"time_audit")
        metrics["time_audit"].append(audit)
    metrics["report_source_sha256"]=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    metrics["plot_source_sha256"]=hashlib.sha256(Path("examples/compatible_energy_plot.py").read_bytes()).hexdigest()
    metrics["serialization_source_sha256"]=hashlib.sha256(Path("examples/verification_records.py").read_bytes()).hexdigest()
    write_record(directory/"metrics.json",metrics)
    plot(metrics,directory);report(metrics)
    return metrics


if __name__=="__main__":
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--reuse",action="store_true")
    verify(reuse=parser.parse_args().reuse)
